import{_ as e,o as a,c as n,a2 as l}from"./chunks/framework.BXzK3EA4.js";const s="/assets/720eaa1739931b35.CnEb0pNX.png",c=JSON.parse('{"title":"Linux System BT Panel Installation Tutorial","description":"","frontmatter":{"title":"Linux System BT Panel Installation Tutorial"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/linux-system-bt-panel-installation-tutorial.md","filePath":"operations-knowledge-base/operating-system/linux/linux-system-bt-panel-installation-tutorial.md","lastUpdated":1794311093000}'),o={name:"operations-knowledge-base/operating-system/linux/linux-system-bt-panel-installation-tutorial.md"};function i(r,t,p,d,h,m){return a(),n("div",null,[...t[0]||(t[0]=[l('<ol><li>Installation Requirements:</li></ol><p>1.Memory: 512MB or more, recommended 768MB or more (the panel itself occupies approximately 60MB of memory).</p><p>2.Disk Space: 300MB or more of available disk space (the panel itself occupies approximately 20MB of disk space).</p><p>3.Operating System: CentOS 7.1+ (Ubuntu 16.04+, Debian 9.0+). Make sure it is a clean operating system without any previously installed Apache/Nginx/php/MySQL/pgsql/gitlab/java environments (existing environments cannot be installed).</p><p>4.Architecture: x86_64.</p><p>5.Baota Linux 7.0 is based on CentOS 7, so it is necessary to use CentOS 7.x system. Note: CentOS officially announced the end of support for CentOS 6 in 2020, and major software developers are gradually ceasing compatibility with CentOS</p><p>Note: CentOS officially announced the end of maintenance and updates for CentOS 6 in 2020. Major software developers are also gradually ceasing compatibility with CentOS 6. It is not recommended to use CentOS 6 for new servers.</p><ol start="2"><li>Installation Method for Baota Linux Panel 7.9.0:</li></ol><p>Official support for CentOS 8 has been discontinued. Please switch to CentOS 7 or CentOS 8 Stream to install Baota Linux Panel. Here are the detailed</p><p>instructions:<a href="https://www.bt.cn/bbs/thread-82931-1-1.html" target="_blank" rel="noreferrer">https://www.bt.cn/bbs/thread-82931-1-1.html</a></p><p>1.CentOS Installation Command:</p><p>Yum install -y wget &amp;&amp; wget -O install.sh <a href="https://download.bt.cn/install/install%5C_6.0.sh" target="_blank" rel="noreferrer">https://download.bt.cn/install/install\\_6.0.sh</a> &amp;&amp; sh install.sh 12f2c1d72</p><p>2.Ubuntu/Deepin Installation Command:</p><p>wget -O install.sh <a href="https://download.bt.cn/install/install-ubuntu%5C_6.0.sh" target="_blank" rel="noreferrer">https://download.bt.cn/install/install-ubuntu\\_6.0.sh</a> &amp;&amp; sudo bash install.sh 12f2c1d72</p><p>3.Debian Installation Command:</p><p>wget -O install.sh <a href="https://download.bt.cn/install/install-ubuntu%5C_6.0.sh" target="_blank" rel="noreferrer">https://download.bt.cn/install/install-ubuntu\\_6.0.sh</a> &amp;&amp; bash install.sh 12f2c1d72</p><p>4.Fedora Installation Command:</p><p>wget -O install.sh <a href="https://download.bt.cn/install/install%5C_6.0.sh" target="_blank" rel="noreferrer">https://download.bt.cn/install/install\\_6.0.sh</a> &amp;&amp; bash install.sh 12f2c1d72</p><p>5.Linux Panel 7.9.8 Upgrade:</p><p>curl <a href="https://download.bt.cn/install/update%5C_panel.sh%7Cbash" target="_blank" rel="noreferrer">https://download.bt.cn/install/update\\_panel.sh|bash</a></p><ol start="3"><li>If the above nodes are not accessible, please use the following alternate nodes for installation:</li></ol><p>1.Alternate Node Guangdong:</p><p>yum install –y wget &amp;&amp; wget –O install.sh <a href="http://125.88.182.172:5880/install/install" target="_blank" rel="noreferrer">http://125.88.182.172:5880/install/install</a> 6.0.sh &amp;&amp; sh install.sh</p><p>2.Alternate Node Hong Kong:</p><p>yum install –y wget &amp;&amp; wget –O install.sh <a href="http://103.224.251.67:5880/install/install" target="_blank" rel="noreferrer">http://103.224.251.67:5880/install/install</a> 6.0sh &amp;&amp; sh install.sh</p><p>3.Alternate Node United States:</p><p>Yum install –y wget &amp;&amp; wget –O install.sh <a href="http://128.1.164.196:5880/install/install" target="_blank" rel="noreferrer">http://128.1.164.196:5880/install/install</a> 6.0.sh &amp;&amp; sh install.sh</p><p>After connecting to your Linux server using SSH tools such as Xshell or PuTTY, execute the corresponding command based on your system to start the installation (it takes about 2 minutes to complete the panel installation). After the installation is complete, you will be prompted with login information. If you need to change the password, restart Baota, modify the port, uninstall Baota, or perform other operations, you can simply enter &quot;bt&quot; to display the corresponding operation options, as shown in the figure below. Follow the prompts to complete the operation.</p><p><img src="'+s+'" alt=""></p><ol start="4"><li>Linux Panel 7.9.8 Update Features:</li></ol><p>1.Added RSA encryption verification mechanism for login form data.</p><ol start="2"><li><p>Added encryption storage mechanism for sensitive data such as usernames and passwords.</p></li><li><p>Optimized encryption mechanism for key data transmission and session binding to prevent replay attacks.</p></li><li><p>Synchronized bug fixes that have been verified in some test versions.</p></li></ol>',32)])])}const f=e(o,[["render",i]]);export{c as __pageData,f as default};
